/* The portal published seven APIs and none of their specifications.
 *
 * `api_spec()` generated an OpenAPI document from this marketplace's own
 * endpoint rows, which is right for the handful of operations the sandbox can
 * execute and wrong as an answer to "where is the Swagger". A developer
 * integrating against a TM Forum API wants TM Forum's document — every
 * operation, every schema, the version number the standard actually carries —
 * and what the portal offered was a nine-endpoint summary of our own making.
 *
 * The seven files now live in `public/specs`, byte-for-byte as retrieved from
 * the 6D reference library (Reference_Documents/TMForum/Open_APIs), so the
 * download a developer gets is the file, not a rendering of it. This table
 * records what each one is and every operation it declares — 146 across the
 * seven, against the 20 the marketplace itself exposes.
 *
 * The version numbers come from the files rather than from us, and that moves
 * five of the seven onto 4.0 or above:
 *
 *   TMF620 Product Catalog Management  5.0.0   (was 2.1)
 *   TMF622 Product Ordering            4.0.0   (was 1.3)
 *   TMF637 Product Inventory           4.0.0   (was 1.1)
 *   TMF687 Stock Management            4.0.0   (was 1.0)
 *   TMF688 Event                       4.0.0   (was 1.1)
 *
 * Two things the files themselves made visible:
 *
 *   - Our Inventory API claimed **TMF685**, which is Resource Pool Management.
 *     There is no TMF685 in the library because the API we describe — stock on
 *     hand, listing visibility — is **TMF687 Stock Management**, and that file
 *     is there, at 4.0.0 with forty operations. The number is corrected.
 *   - The files filed under TMF678 and TMF632 are 6D's own implementations at
 *     v1.0.0 serving from localhost, not TM Forum's v4 standards. They are
 *     loaded as what they are, flagged `is_tmf_standard = false` with the
 *     reason on the row, because recording them as 4.0 would be inventing a
 *     version number no file supports.
 *
 * TMF620's deprecated version becomes 4.0 rather than 2.0 — the real
 * predecessor of the 5.0 document — which keeps Kestrel's migration story and
 * its 2026-12-31 sunset intact and true.
 */

begin;

create table if not exists api_specs (
  id               text primary key,
  api_id           text not null references operator_apis(id) on delete cascade,
  version_id       text,
  tmf              text not null,
  title            text not null,
  declared_version text not null,
  spec_format      text not null,
  servers          text[] not null default '{}',
  file_path        text not null,
  file_bytes       int not null,
  sha256           text not null,
  source_file      text not null,
  drive_file_id    text,
  retrieved_on     date not null default current_date,
  operation_count  int not null,
  /* Whether this really is the TM Forum standard at the version it claims.
     False is not a defect to hide — it is the answer to "why does this one say
     1.0.0", and it has to be readable on the screen that says so. */
  is_tmf_standard  boolean not null default true,
  note             text,
  operations       jsonb not null,
  constraint api_specs_nonstandard_says_why check (
    is_tmf_standard or coalesce(note, '') <> ''
  ),
  constraint api_specs_has_operations check (operation_count > 0)
);

alter table api_specs enable row level security;
drop policy if exists anyone_reads_api_specs on api_specs;
create policy anyone_reads_api_specs on api_specs for select using (true);
drop policy if exists operator_writes_api_specs on api_specs;
create policy operator_writes_api_specs on api_specs for all
  using (current_persona() = 'operator') with check (current_persona() = 'operator');

/* ---- The versions the files declare -------------------------------------- */

alter table api_endpoints drop constraint api_endpoints_version_id_fkey;
alter table operator_api_subscriptions drop constraint operator_api_subscriptions_version_id_fkey;

create temporary table ver_map (old_id text, new_id text, new_version text, new_base text) on commit drop;
insert into ver_map values
  ('AP-CAT@2.0', 'AP-CAT@4.0.0', '4.0.0', '/tmf-api/productCatalogManagement/v4'),
  ('AP-CAT@2.1', 'AP-CAT@5.0.0', '5.0.0', '/tmf-api/productCatalogManagement/v5'),
  ('AP-ORD@1.3', 'AP-ORD@4.0.0', '4.0.0', '/tmf-api/productOrderingManagement/v4'),
  ('AP-SUB@1.1', 'AP-SUB@4.0.0', '4.0.0', '/tmf-api/productInventory/v4'),
  ('AP-INV@1.0', 'AP-INV@4.0.0', '4.0.0', '/tmf-api/stock/v4'),
  ('AP-EVT@1.1', 'AP-EVT@4.0.0', '4.0.0', '/tmf-api/event/v4'),
  ('AP-SET@1.2', 'AP-SET@1.0.0', '1.0.0', '/tmf/customerBill'),
  ('AP-PTY@1.0', 'AP-PTY@1.0.0', '1.0.0', '/tmf/partyManagement');

update api_versions v set id = m.new_id, version = m.new_version, base_path = m.new_base
  from ver_map m where v.id = m.old_id;
update api_endpoints e set version_id = m.new_id from ver_map m where e.version_id = m.old_id;
update operator_api_subscriptions s set version_id = m.new_id, version = m.new_version
  from ver_map m where s.version_id = m.old_id;
update api_call_log l set version_id = m.new_id from ver_map m where l.version_id = m.old_id;

alter table api_endpoints add constraint api_endpoints_version_id_fkey
  foreign key (version_id) references api_versions(id) on delete cascade;
alter table operator_api_subscriptions add constraint operator_api_subscriptions_version_id_fkey
  foreign key (version_id) references api_versions(id);

/* TMF620 v4 is what Kestrel integrated against, and v5 is what replaced it. */
update api_versions set migration_note =
  '5.0.0 replaces the single `price` field with `productOfferingPrice[]`, one entry per market and currency. '
  || 'A 4.0 caller reading `price` gets the seller''s home-market price and will misquote every other market. '
  || 'Move to 5.0.0 and read the entry whose market matches the order.'
 where id = 'AP-CAT@4.0.0';

/* An API named after a standard it does not implement sends every developer
   who looks it up to the wrong document. */
update operator_apis set standard = 'TMF687' where id = 'AP-INV' and standard = 'TMF685';

