on conflict (id) do update set
  tmf = excluded.tmf, title = excluded.title, declared_version = excluded.declared_version,
  spec_format = excluded.spec_format, servers = excluded.servers, file_path = excluded.file_path,
  file_bytes = excluded.file_bytes, sha256 = excluded.sha256, operation_count = excluded.operation_count,
  is_tmf_standard = excluded.is_tmf_standard, note = excluded.note, operations = excluded.operations;

do $$
declare n int; bad text;
begin
  select count(*) into n from api_specs;
  if n <> 7 then raise exception 'expected a specification for all seven APIs, found %', n; end if;

  select string_agg(s.tmf, ', ') into bad from api_specs s
   where not exists (select 1 from api_versions v where v.id = s.version_id);
  if bad is not null then raise exception 'specifications attached to no version: %', bad; end if;

  select string_agg(a.id, ', ') into bad from operator_apis a
   where not exists (select 1 from api_specs s where s.api_id = a.id);
  if bad is not null then raise exception 'published APIs with no specification: %', bad; end if;

  /* The point of the exercise: the reference is the file's operations, not our
     twenty. If this ever drops to what we expose, the specs stopped loading. */
  select sum(operation_count) into n from api_specs;
  if n < 100 then raise exception 'only % operations across seven specifications', n; end if;

  select string_agg(v.id || ' (' || v.version || ')', ', ') into bad
    from api_versions v join api_specs s on s.api_id = v.api_id
   where s.is_tmf_standard and split_part(v.version, '.', 1)::int < 4;
  if bad is not null then raise exception 'standard APIs still below 4.0: %', bad; end if;
end $$;

commit;
